          "title": "From Then",
          "type": "string"
        },
        "kept_as": {
          "description": "The words of the requirement, copied exactly, that say the same thing",
          "title": "Kept As",
          "type": "string"
        }
      },
      "required": [
        "from_then",
        "kept_as"
      ],
      "title": "DutyKept",
